import React, { useState } from "react";

function LoginForm({ onLogin, onRegisterClick }) {
  const [identifier, setIdentifier] = useState(""); // 🔁 email বা mobile
  const [password, setPassword] = useState("");
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      const res = await fetch("http://localhost:8080/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ identifier, password }), // ✅ use identifier
      });

      if (!res.ok) {
        throw new Error("Login failed. Please check your credentials.");
      }

      const token = await res.text();

      // ✅ টোকেন লোকালস্টোরেজে সেভ করা হচ্ছে
      localStorage.setItem("token", token);

      onLogin(token);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <form onSubmit={handleSubmit} style={styles.form}>
        <h1 style={styles.title}>Welcome Back</h1>
        <p style={styles.subtitle}>Please login to continue</p>

        <input
          type="text"
          placeholder="Email or Mobile"
          value={identifier}
          onChange={(e) => setIdentifier(e.target.value)}
          required
          style={styles.input}
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          style={styles.input}
        />

        <button type="submit" style={styles.button} disabled={loading}>
          {loading ? "Logging in..." : "Login"}
        </button>

        {error && <p style={styles.error}>{error}</p>}

        <p style={styles.switchText}>
          Don't have an account?{" "}
          <span onClick={onRegisterClick} style={styles.link}>
            Register now
          </span>
        </p>
      </form>
    </div>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "#eef1f5",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    padding: "20px",
  },
  form: {
    backgroundColor: "#ffffff",
    padding: "40px",
    borderRadius: "16px",
    boxShadow: "0 12px 24px rgba(0,0,0,0.1)",
    maxWidth: "400px",
    width: "100%",
  },
  title: {
    fontSize: "28px",
    marginBottom: "10px",
    fontWeight: "700",
    color: "#222",
    textAlign: "center",
  },
  subtitle: {
    fontSize: "14px",
    marginBottom: "30px",
    textAlign: "center",
    color: "#666",
  },
  input: {
    width: "100%",
    padding: "14px",
    marginBottom: "20px",
    borderRadius: "8px",
    border: "1px solid #ccc",
    fontSize: "16px",
  },
  button: {
    width: "100%",
    padding: "14px",
    backgroundColor: "#0069d9",
    color: "white",
    fontWeight: "600",
    border: "none",
    borderRadius: "8px",
    fontSize: "16px",
    cursor: "pointer",
  },
  error: {
    marginTop: "15px",
    color: "#d9534f",
    textAlign: "center",
  },
  switchText: {
    marginTop: "20px",
    fontSize: "14px",
    textAlign: "center",
    color: "#666",
  },
  link: {
    color: "#007bff",
    cursor: "pointer",
    fontWeight: "600",
    textDecoration: "underline",
    marginLeft: "4px",
  },
};

export default LoginForm;
